// NOTE: You MUST include the panelOptions: when launching this screen or no contents will appear!
interface ProfilePageOptions {
	onlyChallenges: boolean; // only show (and, importantly for in-game perf, create) the Challenges tab.  Also changes the screen's title.
	noCustomize?: boolean; // if this exists and is TRUE, the Customize tab will not be present
	focusTab: ProfileTabType; // which tab should be focused on display the page, only usable if all tabs should be displayed (no only show)
}

export enum ProfileTabType {
	NONE = -1,
	PROGRESS = 0,
	CHALLENGES = 1,
	CUSTOM = 2,
}

